// A fiber: { type, child, sibling, return } — React's exact pointer fields.
function fib(type, children = []) {
  const node = { type, child: null, sibling: null, return: null };
  let prev = null;
  for (const c of children) {
    c.return = node;
    if (prev) prev.sibling = c; else node.child = c;
    prev = c;
  }
  return node;
}
const root = fib('App', [
  fib('Header'),
  fib('List', [fib('Item-a'), fib('Item-b')]),
  fib('Footer'),
]);

